function metricGlyph(i){const paths=['<path d="M20 11a7 7 0 0 1-7 7H6l-4 3 1-6a7 7 0 0 1-1-4 7 7 0 0 1 7-7h4a7 7 0 0 1 7 7Z"/><path d="M7 9h8M7 13h5"/>','<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>','<path d="M12 2v20m5-16H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H6" transform="translate(0 -1) scale(1 .92)"/>','<path d="M4 10a8 8 0 1 1 0 5M4 4v6h6"/>'];const c=[0,1,5,4][i];return '<div class="glyph" style="--color:'+colors[c]+';--tint:'+tints[c]+'"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[i]+'</svg></div>'}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons=['♕','♧','◎','▱','↗','$','♧','♙','✧'],colors=['#3477ec','#8747ed','#00aa82','#f27927','#e8a500','#0bac69','#7770ed','#e4509b','#9b64e8'],tints=['#e1edff','#eee8ff','#d8faeb','#ffead6','#fff4cc','#dcffeb','#e8e9ff','#fce5f2','#f0e7ff'];
const names=['Leadership','People & Culture','Talent & Hiring','Difficult Conversations','Scale & Growth Strategy','Financial Strategy','Innovation & Product','Sales & Marketing','Strategic Planning','Executive Coaching'];
const tags=['Build executive presence and lead with confidence','Create thriving team environments','Attract and retain top talent','Navigate challenging discussions with ease','Scale your business to the next level','Master business finances and profitability','Build products customers love','Generate leads and close deals','Create winning business strategies','1-on-1 personalized guidance'];
const desc=['Develop your leadership skills, build executive presence, and learn how to inspire and guide your team effectively.','Foster a positive workplace culture, improve team dynamics, and create an environment where people thrive.','Master the art of recruiting, interviewing, and retaining the best talent for your organization.','Handle tough conversations with confidence, from performance reviews to conflict resolution and feedback delivery.','Strategic frameworks for sustainable growth, market expansion, and scaling operations while maintaining quality and culture.','Advanced financial planning, cash flow management, and building a sustainable business model.','Product strategy, innovation frameworks, customer discovery, and launching new offerings that drive business growth.','Master sales techniques, marketing strategies, and building a predictable revenue pipeline.','Long-term strategic planning, competitive analysis, and executing strategic initiatives.','Personalized guidance with tailored insights and advanced capabilities.'];
const initial={agents:names.map((name,i)=>({name,tag:tags[i],desc:desc[i],icon:i%9,favorite:false,tier:i===9?'Premium':'Free'})),qa:[{question:'What makes a great leader?',answer:'Great leaders combine vision, empathy, and decisiveness. They inspire their teams through clear communication, lead by example, and create an environment where people feel valued and empowered to contribute their best work.',category:'Leadership Basics',agent:0},{question:'How do I handle a difficult employee?',answer:'Address the issue promptly and privately. Focus on specific behaviors rather than personality. Listen to their perspective, clearly communicate expectations, and agree on concrete next steps with timelines. Document the conversation and follow up regularly.',category:'Management',agent:0},{question:'What are the key metrics for team performance?',answer:'Choose metrics that align with your team objectives: productivity, quality, engagement, efficiency, and goal achievement. Review the results with your team regularly.',category:'Performance',agent:0}],files:[{name:'Leadership Fundamentals Guide',type:'Document',size:'2.4 MB',agent:0},{name:'Executive Presence Masterclass',type:'Video',size:'145 MB',agent:0},{name:'Team Building Best Practices',type:'Document',size:'1.8 MB',agent:0},{name:'Harvard Business Review Articles',type:'Link',size:'External link',agent:0},{name:'Performance Review Templates',type:'Document',size:'890 KB',agent:0}],pending:[{question:'How do I transition from manager to executive?',users:3,agent:0},{question:'Dealing with board member conflicts',users:2,agent:0},{question:'Leading through a company merger',users:1,agent:0}],plan:'Professional',profile:{name:'Emily Johnson',email:'emily@coachingbusiness.com'},drafts:[]};
let db;try{db=JSON.parse(localStorage.getItem('xpertloop-v1'))||structuredClone(initial)}catch{db=structuredClone(initial)}
let route='home',agentId=0,tab='chat',contentTab='files',dashAgent=0,messages={},draft={},step=1,uploadType='Document',chosenFiles=[],generated='',toastTimer;
function save(){try{localStorage.setItem('xpertloop-v1',JSON.stringify(db))}catch{toast('Browser storage is full. Your changes remain in this session.')}}
function glyph(i){return `<div class="glyph" style="--color:${colors[i%9]};--tint:${tints[i%9]}">${icons[i%9]}</div>`}
function toast(t){$('#toast').textContent='✓  '+t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function go(r){location.hash=r}function openAgent(i){agentId=i;tab='chat';go('agent-'+i);if(route==='agent-'+i)render()}
function nav(){ $('#nav').innerHTML=[["home","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z\"/></svg>","Home"],["agents","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"5\" y=\"7\" width=\"14\" height=\"13\" rx=\"3\"/><path d=\"M12 3v4M2 12v4m20-4v4M9 16h6\"/><circle cx=\"9\" cy=\"12\" r=\".75\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"12\" r=\".75\" fill=\"currentColor\"/><circle cx=\"12\" cy=\"3\" r=\"1\" fill=\"currentColor\"/></svg>","Agents"],["dashboard","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 3v17h17M8 16v-4m5 4V8m5 8V5\"/></svg>","Dashboard"]].map(([r,i,n])=>`<button onclick="go('${r}')" class="${route===r||r==='agents'&&route.startsWith('agent-')?'active':''}" title="${n}"><span>${i}</span>${n}</button>`).join('')}
function render(){route=location.hash.slice(1)||'home';if(route.startsWith('agent-')){agentId=Number(route.split('-')[1]);if(!db.agents[agentId]){go('agents');return}}nav();const titles={home:'Home',agents:'Agents',dashboard:'Dashboard',create:'Content studio',billing:'Billing & Plans',plans:'Change plan',profile:'Profile settings',account:'Account settings',notifications:'Notifications',support:'Help & support'};$('#crumb').innerHTML=route.startsWith('agent-')?`<a href="#agents">Agents</a><span>/</span><strong>${esc(db.agents[agentId].name)}${agentId===0?' Coach':''}</strong>`:route==='plans'?'<a href="#billing">Billing &amp; Plans</a><span>/</span><strong>Change plan</strong>':'';let html=route==='home'?home():route==='agents'?agents():route==='dashboard'?dashboard():route.startsWith('agent-')?agent():route==='create'?studio():route==='billing'?billing():route==='plans'?plans():settings(route);$('#app').innerHTML='<div class="page">'+html+'</div>';animateNumbers()}
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0)});
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
const stats=[['Total Sessions','1,004','+220 from last month','↑ 28.12%',0],['Active Paying Clients','193','−2 from last month','↓ 1.03%',1],['Monthly Revenue','$5,200','+$210 from last month','↑ 4.2%',5],['Return Rate','72%','+5% from last month','↑ 7.46%',4]];
function metrics(simple=false){return `<div class="grid four metrics">${stats.map((s,i)=>`<button class="card metric" onclick="metricDetail(${i})"><div class="metric-top">${metricGlyph(i)}<span class="badge">↗</span></div><small>${s[0]}</small><div class="number" data-count="${s[1]}">${s[1]}</div><div class="change"><span>${s[2]}</span><b class="${i===1?'red':'green'}">${s[3]}</b></div></button>`).join('')}</div>`}
function home(){return `<div class="hero"><div class="eyebrow">YOUR EXPERTISE, AMPLIFIED</div><h1>Good morning, Emily <span style="font-size:27px">☀</span></h1><p>Your knowledge is making an impact. What would you like to do today?</p></div><div class="grid two home-actions"><div class="card" role="button" tabindex="0" onclick="go('agents')" onkeydown="if(event.key==='Enter')go('agents')"><span class="arrow">↗</span>${glyph(0)}<h2>See my agents</h2><p>Give your clients guidance that sounds like you. Manage your agents and see the difference they're making.</p><small><span class="status">4 agents active</span> &nbsp; · &nbsp; 1,004 sessions this month</small></div><div class="card" role="button" tabindex="0" onclick="go('create')" onkeydown="if(event.key==='Enter')go('create')"><span class="arrow">↗</span>${glyph(8)}<h2>Create content</h2><p>Turn your expertise and your audience's questions into content worth sharing. All in your voice.</p><small>LinkedIn, Instagram, X &nbsp; · &nbsp; AI-assisted</small></div></div><div class="section-title"><h2>Your impact at a glance</h2><button class="text-button" onclick="go('dashboard')">View dashboard ↗</button></div>${metrics()}<div class="card"><div class="page-heading" style="margin:0"><div><span class="status">Knowledge opportunity</span><h3 style="margin:10px 0 5px">Your clients are asking. You have the answers.</h3><p style="font-size:12px;margin:0">${db.pending.length} questions are waiting for your expertise.</p></div><button class="secondary" onclick="agentId=0;tab='analytics';go('agent-0')">Review questions →</button></div></div>`}
function agents(){return heading('Your agents','A little more of you. A lot more possibility.',`<button class="primary" onclick="newAgent()">＋ Add new agent</button>`)+`<div class="page-heading"><span class="badge">${db.agents.length} agents in your workspace</span><input style="width:230px;padding:9px 12px" placeholder="Search agents…" aria-label="Search agents" oninput="filterAgents(this.value)"></div><div class="grid two" id="agent-grid">${agentCards()}</div>`}
function agentCards(filter=''){return db.agents.map((a,i)=>({...a,id:i})).filter(a=>(a.name+' '+a.tag).toLowerCase().includes(filter.toLowerCase())).map(a=>`<article class="card agent-card"><button class="favorite ${a.favorite?'on':''}" aria-label="${a.favorite?'Remove favorite':'Favorite agent'}" onclick="favorite(${a.id},this)">${a.favorite?'★':'☆'}</button>${glyph(a.icon)}<h3>${esc(a.name)} <span style="font-weight:400;color:#aeb6c2">/</span> ${esc(a.tag)}</h3><p>${esc(a.desc)}</p><div class="card-footer"><button class="secondary" onclick="openAgent(${a.id})">Open agent →</button><span class="status">Active</span></div></article>`).join('')||'<p>No agents match your search.</p>'}
function filterAgents(v){$('#agent-grid').innerHTML=agentCards(v)}function favorite(i,b){db.agents[i].favorite=!db.agents[i].favorite;b.classList.toggle('on');b.textContent=db.agents[i].favorite?'★':'☆';save()}
function lineChart(values=[45,52,48,51,47,50,49],labels=['Jan 7','Jan 8','Jan 9','Jan 10','Jan 11','Jan 12','Jan 13'],color='#008ac7',money=false){let max=Math.max(...values)*1.2;let pts=values.map((v,i)=>[45+i*650/(values.length-1),195-v/max*165]);return `<svg class="chart" viewBox="0 0 730 230" role="img" aria-label="${money?'Revenue':'Session'} trend">${[0,1,2,3].map(i=>`<line x1="45" y1="${30+i*55}" x2="695" y2="${30+i*55}" stroke="#e8edf3" stroke-dasharray="4 4"/><text x="3" y="${34+i*55}">${money?'$':''}${Math.round(max*(1-i/3))}</text>`).join('')}${money?`<polygon points="45,195 ${pts.map(p=>p.join(',')).join(' ')} 695,195" fill="${color}" opacity=".08"/>`:''}<polyline class="draw" points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="${color}"><title>${labels[i]}: ${money?'$':''}${values[i]}</title></circle><text x="${p[0]}" y="220" text-anchor="middle">${labels[i]}</text>`).join('')}</svg>`}
function dashboard(){return heading('Your business, in focus','A clear picture of your impact, across every agent.',`<span class="badge">This month · Demo data</span>`)+metrics()+`<div class="grid two"><div class="card"><h2>Revenue</h2><p style="font-size:11px">Six months of growing your impact</p>${lineChart([2800,3200,3600,4200,4800,5200],['Jul','Aug','Sep','Oct','Nov','Dec'],'#0ab88b',true)}</div><div class="card"><h2>Agent performance</h2><p style="font-size:11px">Sessions by agent this month</p><div class="donut-layout"><div class="donut" role="img" aria-label="Sessions by agent"></div><div class="legend"><div><b style="font-size:25px">1,004</b><small>total sessions</small></div>${[342,267,219,176].map((v,i)=>`<div><span><i class="dot" style="background:${['#92c4ff','#a58cf5','#efa4cf','#ffdb65'][i]}"></i>${names[i]}</span><b>${v}</b></div>`).join('')}</div></div></div></div><div class="card" style="margin-top:24px"><div class="page-heading"><h2>Questions by agent</h2><select aria-label="Select agent" style="width:220px" onchange="dashAgent=Number(this.value);render()">${db.agents.map((a,i)=>`<option value="${i}" ${dashAgent===i?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="grid two"><div><h3>Top questions</h3>${topQuestions(dashAgent).slice(0,3).map((q,i)=>`<div class="question-row"><span>${q}</span><span style="color:var(--blue);white-space:nowrap">${52-i*7} times</span></div>`).join('')}<button class="text-button" onclick="agentId=dashAgent;tab='analytics';go('agent-'+dashAgent)">See more →</button></div><div><h3>Unanswered questions</h3>${db.pending.filter(q=>q.agent===dashAgent).slice(0,3).map(q=>`<div class="question-row"><span>${esc(q.question)}</span><button class="text-button" onclick="answerQuestion(${db.pending.indexOf(q)})">Answer →</button></div>`).join('')||'<p style="font-size:12px">No unanswered questions. Your knowledge is up to date.</p>'}<button class="text-button" onclick="agentId=dashAgent;tab='analytics';go('agent-'+dashAgent)">See more →</button></div></div><div style="text-align:center;margin-top:20px"><button class="primary" onclick="go('create')">✧ Create content for ${esc(db.agents[dashAgent].name)}</button></div></div>`}
function topQuestions(i){return i===0?['How can I improve my executive presence?','What are effective leadership communication strategies?','How do I handle team conflicts?','Tips for delegating effectively','How to motivate underperforming employees?']:[`How can I improve my ${db.agents[i].name.toLowerCase()} skills?`,`Where should I start with ${db.agents[i].name.toLowerCase()}?`,'What practical steps can I take this week?']}
function agent(){let a=db.agents[agentId];return `<div class="agent-heading"><button class="outline" onclick="go('agents')">← Back</button>${glyph(a.icon)}<div><h2>${esc(a.name)}${agentId===0?' Coach':''}</h2><p>${esc(a.tag)}</p></div><div class="tabs">${['chat','analytics','content'].map(t=>`<button class="${tab===t?'selected':''}" onclick="tab='${t}';render()">${{"chat":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 2 2-6a8.5 8.5 0 1 1 18-4.5Z\"/></svg> Chat","analytics":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 3v17h17M8 16v-4m5 4V8m5 8V5\"/></svg> Analytics","content":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15\"/></svg> Content"}[t]}</button>`).join('')}</div><span class="status">Active</span></div>${tab==='chat'?chat():tab==='analytics'?analytics():content()}`}
function chat(){let a=db.agents[agentId],m=messages[agentId]||[];return `<div class="chat"><div class="chat-messages" id="messages"><div class="message">${glyph(a.icon)}<div class="bubble">Hi! I'm your ${esc(a.name.toLowerCase())} coach. I'm here to help you ${esc(a.tag.toLowerCase())}.<br><br>What would you like to work on today?</div></div>${m.map(x=>`<div class="message ${x.role}">${x.role==='user'?'':glyph(a.icon)}<div class="bubble">${esc(x.text)}</div></div>`).join('')}${!m.length?`<div class="suggestions"><p style="font-size:11px">✧ A few places to start</p><div class="grid two">${topQuestions(agentId).slice(0,4).map(q=>`<button onclick="sendChat(${esc(JSON.stringify(q))})">${q} ↗</button>`).join('')}</div></div>`:''}</div><form class="composer" onsubmit="event.preventDefault();sendChat()"><textarea rows="1" id="chat-input" placeholder="Ask your coach anything…" aria-label="Message your agent" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChat()}"></textarea><button class="primary" type="submit">Send ↗</button></form><p class="demo-note">Prototype responses · Uses your saved Q&A · Enter to send</p></div>`}
function sendChat(text){text=(text||$('#chat-input').value).trim();if(!text)return;const id=agentId;messages[id]??=[];messages[id].push({role:'user',text});render();$('#messages').insertAdjacentHTML('beforeend','<div class="message" id="thinking"><div class="bubble thinking"><i></i><i></i><i></i></div></div>');const qa=db.qa.filter(q=>q.agent===id);const words=s=>s.toLowerCase().match(/[a-z]{4,}/g)||[];let best,score=0;qa.forEach(q=>{let exact=q.question.toLowerCase()===text.toLowerCase(),n=words(text).filter(w=>words(q.question).includes(w)).length;if(exact||n>score){score=exact?999:n;best=q}});let answer;if(best&&score>0)answer=best.answer;else if(/executive presence|communication|delegat|conflict|leader/.test(text.toLowerCase())&&id===0)answer='Start with one specific situation you want to improve. Before your next meeting, write down the outcome you want and the one message your team should remember. Communicate that message clearly, invite a different perspective, and agree on a concrete next step.\n\nWhat is the situation you have in mind?';else{answer="I don't have enough of this expert's knowledge on that topic yet. I've flagged your question so they can add their perspective. Try asking about a saved Q&A topic, or add an answer in Analytics and ask me again.";if(!db.pending.some(q=>q.question.toLowerCase()===text.toLowerCase()&&q.agent===id)){db.pending.push({question:text,users:1,agent:id});save()}}setTimeout(()=>{messages[id].push({role:'assistant',text:answer});if(route==='agent-'+id&&tab==='chat'){render();$('#chat-input').focus();$('#messages').lastElementChild?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}},1000)}
function analytics(){let pending=db.pending.filter(q=>q.agent===agentId);return `<h2 style="margin-bottom:20px">Performance overview</h2><div class="grid four metrics">${[['Total Sessions','342','+15%',0],['Active Users','156','+8%',1],['Avg. Session Time','9.2m','+12%',4],['Satisfaction','96%','+3%',3]].map(s=>`<div class="card"><div style="display:flex;gap:14px;align-items:center">${glyph(s[3])}<div><small>${s[0]}</small><div class="number" style="margin:5px 0">${s[1]}</div></div></div><small class="green" style="display:block;margin-top:15px">${s[2]} from last week</small></div>`).join('')}</div><div class="card"><h2>Session trends <small style="font-size:11px">/ Last 7 days</small></h2>${lineChart()}</div><div class="grid two" style="margin-top:24px"><div class="card"><h2>Top questions asked</h2>${topQuestions(agentId).map((q,i)=>`<div class="question-row"><span><span class="badge">${i+1}</span> &nbsp;${q}<small>${127-i*13} asks &nbsp; <span class="green">+12%</span></small></span></div>`).join('')}</div><div class="card"><h2>Unanswered questions <span class="badge" style="background:#fff1f2;color:#e75c66">${pending.length} pending</span></h2><p style="font-size:11px">Add your perspective to help your agent answer next time.</p>${pending.map(q=>`<div class="question-row"><div>${esc(q.question)}<small>${q.users} ${q.users===1?'user':'users'} · Awaiting your expertise</small></div><button class="primary" onclick="answerQuestion(${db.pending.indexOf(q)})">Answer</button></div>`).join('')||'<div class="empty">✧<h3 style="margin-top:20px">All caught up</h3><p>Your agent has no unanswered questions.</p></div>'}</div></div>`}
function content(){let files=db.files.filter(f=>f.agent===agentId),qa=db.qa.filter(q=>q.agent===agentId);return heading('Training content library',contentTab==='files'?"A home for the knowledge that makes your agent yours.":'Train your agent with your perspective, one answer at a time.',`<div style="display:flex;gap:12px"><div class="tabs"><button class="${contentTab==='files'?'selected':''}" onclick="contentTab='files';render()">Files</button><button class="${contentTab==='qa'?'selected':''}" onclick="contentTab='qa';render()">Q&A</button></div><button class="primary" onclick="${contentTab==='files'?'uploadModal()':'qaModal()'}">＋ ${contentTab==='files'?'Upload content':'Add Q&A'}</button></div>`)+(contentTab==='files'?`<div class="grid four metrics">${['Document','Video','Link','Total items'].map((t,i)=>`<div class="card"><small>${['▤','▹','↗','↑'][i]} &nbsp;${t==='Document'?'Documents':t==='Video'?'Videos':t==='Link'?'Links':t}</small><div class="number" style="margin-bottom:0">${i===3?files.length:files.filter(f=>f.type===t).length}</div></div>`).join('')}</div><div class="card content-list"><h3 class="list-title">All content (${files.length})</h3>${files.map(f=>`<div class="file-row">${glyph(f.type==='Video'?1:f.type==='Link'?2:0)}<div><h3>${esc(f.name)}</h3><small>${esc(f.size)} &nbsp; · &nbsp; Uploaded by you</small></div><span class="badge">${esc(f.type)} · Added</span><button aria-label="Remove content" class="close" onclick="removeFile(${db.files.indexOf(f)})">×</button></div>`).join('')||'<div class="empty"><h3>Your knowledge starts here</h3><p>Upload your first resource to get started.</p><button class="primary" onclick="uploadModal()">Upload content</button></div>'}</div><p class="demo-note">Demo library: file names are saved locally. Files are not processed or uploaded to an AI service.</p>`:`<div class="card content-list"><h3 class="list-title">All Q&A pairs (${qa.length})</h3>${qa.map(q=>`<div class="qa-row"><span class="badge">${esc(q.category||'General')}</span><h3>${esc(q.question)}</h3><p>${esc(q.answer)}</p><small>Added to your agent's knowledge</small><button style="float:right" class="text-button" onclick="qaModal(${db.qa.indexOf(q)})">Edit answer</button></div>`).join('')||'<div class="empty"><h3>Make it sound like you</h3><p>Add a question your clients ask and answer it in your own words.</p><button class="primary" onclick="qaModal()">＋ Add Q&A</button></div>'}</div>`)}
function removeFile(i){modal('Remove resource',`<p>Remove <b>${esc(db.files[i].name)}</b> from this agent's library?</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" onclick="db.files.splice(${i},1);save();closeModal();render();toast('Resource removed')">Remove</button>`)}
function modal(title,body,footer=''){ $('#overlay').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title.replace(/<[^>]*>/g,''))}"><div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;$('#overlay').onclick=e=>{if(e.target.id==='overlay')closeModal()};setTimeout(()=>$('.modal input,.modal textarea,.modal button')?.focus(),40)}
let previousFocus;function closeModal(){ $('#overlay').innerHTML='';previousFocus?.focus() }document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){let nodes=[...$('.modal').querySelectorAll('button,input,textarea,select,a')].filter(n=>!n.disabled&&n.offsetParent);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}});
function qaModal(edit=-1,pending=-1){previousFocus=document.activeElement;let q=edit>=0?db.qa[edit]:pending>=0?{question:db.pending[pending].question}:{};modal(pending>=0?'Share your expertise':edit>=0?'Edit Q&A':'Add a Q&A pair',`<p style="font-size:12px">Your answer becomes part of your agent's knowledge.</p><form id="qa-form" onsubmit="event.preventDefault();saveQa(${edit},${pending})"><div class="form-group"><label for="q-question">Question *</label><input id="q-question" required value="${esc(q.question||'')}" placeholder="What do your clients want to know?"></div><div class="form-group"><label for="q-answer">Your answer *</label><textarea class="field" id="q-answer" rows="6" required placeholder="Share your approach, in your own words…">${esc(q.answer||'')}</textarea></div><div class="form-group"><label for="q-category">Category</label><input id="q-category" value="${esc(q.category||'')}" placeholder="e.g. Leadership Basics"></div></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="qa-form">Save to agent ✧</button>`)}
function answerQuestion(i){agentId=db.pending[i].agent;qaModal(-1,i)}function saveQa(edit,pending){const q={question:$('#q-question').value.trim(),answer:$('#q-answer').value.trim(),category:$('#q-category').value.trim()||'General',agent:agentId};if(!q.question||!q.answer)return;if(edit>=0)db.qa[edit]=q;else db.qa.push(q);if(pending>=0)db.pending.splice(pending,1);save();closeModal();render();toast(pending>=0?'Knowledge gap filled. Try this question in Chat.':'Q&A saved to your agent')}
function newAgent(){draft={name:'',tag:'',specialization:'',tier:'Free',icon:0,tone:'Warm & encouraging',instructions:''};step=1;agentWizard()}
function readAgentDraft(){if(step===1){draft.name=$('#a-name').value;draft.tag=$('#a-tag').value;draft.specialization=$('#a-specialization').value;draft.tier=$('#a-tier').value}else if(step===2){draft.tone=$('#a-tone').value;draft.instructions=$('#a-instructions').value}}
function agentWizard(){const body=step===1?`<h3>Basic information</h3><form id="agent-form" onsubmit="event.preventDefault();advanceAgent()"><div class="form-group"><label for="a-name">Agent name *</label><input id="a-name" required value="${esc(draft.name)}" placeholder="e.g. Executive Leadership"></div><div class="form-group"><label for="a-tag">Tagline *</label><input id="a-tag" required value="${esc(draft.tag)}" placeholder="A short description of what this agent does"></div><div class="form-group"><label for="a-specialization">Specialization *</label><select required id="a-specialization"><option value="">Select a specialization</option>${names.map(n=>`<option ${draft.specialization===n?'selected':''}>${n}</option>`).join('')}<option ${draft.specialization==='Other'?'selected':''}>Other</option></select></div><div class="form-group"><label for="a-tier">Tier</label><select id="a-tier"><option ${draft.tier==='Free'?'selected':''}>Free</option><option ${draft.tier==='Premium'?'selected':''}>Premium</option></select></div><label>Select icon</label><div class="icon-picker">${icons.map((x,i)=>`<button type="button" aria-label="Select icon ${i+1}" class="${draft.icon===i?'selected':''}" onclick="readAgentDraft();draft.icon=${i};agentWizard()">${glyph(i)}</button>`).join('')}</div></form>`:step===2?`<h3>Give it your voice</h3><p style="font-size:12px">Choose how your agent guides clients. Add training material from its Content tab after creation.</p><form id="agent-form" onsubmit="event.preventDefault();advanceAgent()"><div class="form-group"><label for="a-tone">Communication style</label><select id="a-tone">${['Warm & encouraging','Direct & practical','Thoughtful & reflective','Professional & structured'].map(t=>`<option ${draft.tone===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-group"><label for="a-instructions">Coaching approach</label><textarea class="field" id="a-instructions" rows="6" placeholder="Describe your approach, key principles, and how you want to support your clients…">${esc(draft.instructions)}</textarea></div><div class="review-box"><span class="status">Ready for your knowledge</span><p style="font-size:12px;margin:10px 0 0">You can add books, documents, videos, links, and specific answers once your agent is created.</p></div></form>`:`<div style="display:flex;gap:16px;align-items:center;margin-bottom:25px">${glyph(draft.icon)}<div><h2>${esc(draft.name)}</h2><small>${esc(draft.tag)}</small></div></div><h3>Ready to meet your agent?</h3><div class="review-box"><div class="detail-line"><span>Specialization</span><b>${esc(draft.specialization)}</b></div><div class="detail-line"><span>Tier</span><b>${draft.tier}</b></div><div class="detail-line"><span>Voice</span><b>${esc(draft.tone)}</b></div></div><p style="font-size:12px;margin-top:20px">Next, add your knowledge and try a conversation. This is a browser-local prototype; voice settings are saved for review.</p>`;
modal(`Create new agent <small style="font-size:12px">/ Step ${step} of 3</small>`,body,`<button class="outline" onclick="${step===1?'closeModal()':'readAgentDraft();step--;agentWizard()'}">${step===1?'Cancel':'← Back'}</button><button class="primary" ${step<3?'type="submit" form="agent-form"':'onclick="createAgent()"'}>${step===3?'Create agent ✧':'Next →'}</button>`);$('.modal-head').insertAdjacentHTML('afterend',`<div class="progress-track">${[1,2,3].map(i=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div>`)}
function advanceAgent(){readAgentDraft();step++;agentWizard()}function createAgent(){db.agents.push({...draft,desc:draft.instructions||draft.tag,favorite:false});save();closeModal();openAgent(db.agents.length-1);toast('Your new agent is ready. Add knowledge in Content.')}
function uploadModal(){uploadType='Document';chosenFiles=[];showUpload()}
function showUpload(){modal('Upload training content',`<p style="font-size:12px">Add resources to your agent's knowledge library.</p><div class="tabs" style="width:100%">${['Document','Video','Link'].map(t=>`<button class="${uploadType===t?'selected':''}" onclick="uploadType='${t}';chosenFiles=[];showUpload()">${{Document:'▤',Video:'▹',Link:'↗'}[t]} ${t}</button>`).join('')}</div>${uploadType==='Link'?`<form id="upload-form" onsubmit="event.preventDefault();finishUpload()"><div class="form-group" style="margin-top:24px"><label for="link-title">Resource title *</label><input required id="link-title" placeholder="e.g. My leadership framework"></div><div class="form-group"><label for="link-url">External URL *</label><input required type="url" id="link-url" placeholder="https://"></div></form>`:`<div class="dropzone" tabindex="0" role="button" aria-label="Choose files" onclick="$('#file-input').click()" onkeydown="if(event.key==='Enter')$('#file-input').click()" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="event.preventDefault();this.classList.remove('drag');selectFiles(event.dataTransfer.files)"><div class="upload-icon">↥</div><h3>Drag and drop files here</h3><p style="font-size:12px;margin:0">or click to browse your computer</p><small>${uploadType==='Document'?'PDF, DOC, DOCX, TXT':'MP4, MOV, AVI'} · Maximum 500 MB per file</small></div><input hidden id="file-input" type="file" multiple accept="${uploadType==='Document'?'.pdf,.doc,.docx,.txt':'.mp4,.mov,.avi'}" onchange="selectFiles(this.files)"><div id="file-selection"></div>`}<p class="demo-note">Prototype: saves resource metadata locally. No AI processing.</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button id="upload-button" class="primary" ${uploadType==='Link'?'type="submit" form="upload-form"':'disabled onclick="finishUpload()"'}>${uploadType==='Link'?'Add link':'Upload files'} ↑</button>`)}
function selectFiles(files){const allow=uploadType==='Document'?/\.(pdf|docx?|txt)$/i:/\.(mp4|mov|avi)$/i;chosenFiles=[...files].filter(f=>f.size<=500*1024*1024&&allow.test(f.name));if(chosenFiles.length!==files.length)toast('Some files were skipped: check file type and 500 MB limit.');$('#file-selection').innerHTML=chosenFiles.map(f=>`<div class="detail-line"><span>▤ ${esc(f.name)}</span><small>${(f.size/1024/1024).toFixed(1)} MB</small></div>`).join('');$('#upload-button').disabled=!chosenFiles.length}
function finishUpload(){if(uploadType==='Link'){db.files.push({name:$('#link-title').value,type:'Link',url:$('#link-url').value,size:'External link',agent:agentId})}else chosenFiles.forEach(f=>db.files.push({name:f.name,type:uploadType,size:(f.size/1024/1024).toFixed(1)+' MB',agent:agentId}));save();closeModal();render();toast('Resource added to the demo library')}
const planData={Starter:{price:29,agents:2,storage:'5 GB',features:['2 AI coaching agents','Up to 100 Q&A pairs','Basic analytics','Email support','5 GB storage']},Professional:{price:99,agents:10,storage:'50 GB',features:['10 AI coaching agents','Unlimited Q&A pairs','Advanced analytics','Priority support','50 GB storage','Custom branding']},Enterprise:{price:299,agents:Infinity,storage:'Unlimited',features:['Unlimited AI agents','Unlimited Q&A pairs','Enterprise analytics','Dedicated support','Unlimited storage','Custom integrations','API access','White-label options']}};
function billing(){let plan=planData[db.plan];return heading('Billing & plans','Manage your subscription, billing, and payment methods.')+`<div class="grid two"><div class="card"><div style="display:flex;justify-content:space-between"><h2>♕ Current plan</h2><span class="status">Active</span></div><p>You're on the ${db.plan} plan</p><div class="billing-price">$${plan.price} <small>per month</small></div><div class="detail-line" style="border-top:1px solid var(--line)"><span>Next billing date</span><b>December 13, 2026</b></div><div class="detail-line"><span>Billing cycle</span><b>Monthly</b></div><button class="outline" style="width:100%;margin-top:25px" onclick="go('plans')">Change plan →</button></div><div class="card"><h2>▱ Payment method</h2><p>Manage your payment details</p><div class="credit-card"><div style="float:right">Visa</div><div class="chip"></div><h2>•••• ${esc(db.last4||'4242')}</h2><div style="display:flex;justify-content:space-between"><small>${esc(db.profile.name)}</small><small>Exp 12/27</small></div></div><button class="outline" style="width:100%" onclick="paymentModal()">Update payment method</button></div></div><div class="card" style="margin-top:24px"><h2>Usage this month</h2><div class="grid" style="grid-template-columns:repeat(3,1fr);margin-top:25px">${[['AI agents used',`${db.agents.length} / ${isFinite(plan.agents)?plan.agents:'∞'}`,Math.min(100,db.agents.length/plan.agents*100)||20],['Q&A pairs',`${db.qa.length} / ${db.plan==='Starter'?'100':'∞'}`,db.plan==='Starter'?db.qa.length:25],['Storage used',`23.4 GB / ${plan.storage}`,47]].map((s,i)=>`<div><div style="display:flex;justify-content:space-between;font-size:11px;gap:5px"><small>${s[0]}</small><b>${s[1]}</b></div><div class="usage-bar" style="--color:${colors[i]}"><i style="width:${s[2]}%"></i></div></div>`).join('')}</div></div><div class="card content-list" style="margin-top:24px"><div class="list-title"><h2>Billing history</h2><small>Download invoices and view your payment history</small></div><div style="overflow:auto"><table><thead><tr><th>Invoice</th><th>Date</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${['Nov','Oct','Sep','Aug','Jul'].map((m,i)=>`<tr><td>INV-2026-${String(11-i).padStart(3,'0')}</td><td>${m} 13, 2026</td><td>$99.00</td><td><span class="badge green" style="background:#e4fbee">Paid</span></td><td><button class="text-button" onclick="downloadInvoice('${m}',${11-i})">↓ Download</button></td></tr>`).join('')}</tbody></table></div></div><p class="demo-note">Demo billing only. No subscription changes or charges are made.</p>`}
function plans(){return `<button class="text-button" onclick="go('billing')">← Back to billing</button><div style="margin-top:20px">${heading('Change your plan','More space for your expertise to grow.')}</div><div class="grid plans">${Object.entries(planData).map(([n,p],i)=>`<div class="card plan-card ${db.plan===n?'current':''}">${db.plan===n?'<span class="current-label">Current plan</span>':''}${glyph([0,4,8][i])}<h2>${n}</h2><p style="font-size:12px">${['Perfect for getting started','For growing coaching businesses','For established organizations'][i]}</p><div class="billing-price">$${p.price}<small> /month</small></div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul>${db.plan===n?'<button class="outline" disabled>Your current plan</button>':`<button class="primary" onclick="changePlan('${n}')">${p.price>planData[db.plan].price?'Upgrade':'Downgrade'} to ${n}</button>`}</div>`).join('')}</div><div class="card" style="margin-top:24px"><p style="font-size:12px;margin:0"><b>Need help choosing?</b> All plans include the core AI coaching experience. <button class="text-button" onclick="go('support')">Talk to support →</button></p></div>`}
function changePlan(n){let target=planData[n],over=db.agents.length>target.agents||(n==='Starter'&&db.qa.length>100);modal('Change to '+n,`<p>${over?`Your workspace exceeds this plan's limits. You have ${db.agents.length} agents and ${db.qa.length} Q&A pairs. Reduce usage before switching to ${n}.`:`Switch your demo workspace to ${n} at $${target.price}/month?`}</p><div class="review-box">This is a prototype. No payment will be taken and no real subscription will change.</div>`,`<button class="outline" onclick="closeModal()">Cancel</button>${over?'':`<button class="primary" onclick="db.plan='${n}';save();closeModal();go('billing');toast('Demo plan updated to ${n}')">Confirm demo change</button>`}`)}
function paymentModal(){modal('Update demo payment method',`<p style="font-size:12px">Use sample details only. This prototype stores only the last four digits.</p><form id="payment-form" onsubmit="event.preventDefault();db.last4=$('#card-last').value;save();closeModal();render();toast('Demo card updated')"><label for="card-last">Card ending in</label><input required id="card-last" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="4242" aria-label="Last four demo card digits"></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="payment-form">Save demo card</button>`)}
function downloadFile(name,text,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadInvoice(month,n){downloadFile(`Xpertloop-demo-invoice-2026-${n}.txt`,`XPERTLOOP — DEMO INVOICE\nInvoice: INV-2026-${String(n).padStart(3,'0')}\nDate: ${month} 13, 2026\nCustomer: ${db.profile.name}\nPlan: Professional\nAmount: $99.00\nStatus: Paid\n\nPrototype sample only. Not a financial document.`);toast('Sample invoice downloaded')}
function metricDetail(i){const series=[[580,720,890,1050,784,1004],[135,150,165,182,195,193],[2400,3100,3800,4200,4990,5200],[58,62,65,68,67,72]][i],max=Math.max(...series),s=stats[i];modal(s[0],`${metricGlyph(i)}<div class="number" style="font-size:43px;margin:20px 0">${s[1]}</div><div class="change"><span>${s[2]}</span><b class="${i===1?'red':'green'}">${s[3]}</b></div>${i===1?'<div class="grid" style="grid-template-columns:repeat(3,1fr);margin-top:25px"><div class="review-box"><small>Paying</small><h2>193</h2></div><div class="review-box"><small>Free</small><h2>55</h2></div><div class="review-box"><small>Total</small><h2>248</h2></div></div>':''}<h3 style="margin-top:25px">Six-month trend</h3><div class="bars">${series.map((v,j)=>`<div class="bar" style="height:${v/max*170}px;background:${colors[s[4]]}"><b>${i===2?'$':''}${v.toLocaleString()}${i===3?'%':''}</b><small>${['Jul','Aug','Sep','Oct','Nov','Dec'][j]}</small></div>`).join('')}</div><h3>Monthly breakdown</h3><div class="grid" style="grid-template-columns:repeat(3,1fr);gap:10px">${series.map((v,j)=>`<div class="review-box" style="padding:12px"><small>${['Jul','Aug','Sep','Oct','Nov','Dec'][j]}</small><h3 style="margin:5px 0">${i===2?'$':''}${v.toLocaleString()}${i===3?'%':''}</h3><small class="${j&&v<series[j-1]?'red':'green'}">${j?((v-series[j-1])/series[j-1]*100).toFixed(1)+'%':'Base month'}</small></div>`).join('')}</div><p class="demo-note">Illustrative prototype data</p>`)}
function studio(){return heading('Content studio','Your expertise. Fresh perspectives. A voice that’s unmistakably yours.',`<span class="badge">✧ ${db.drafts.length} saved drafts</span>`)+`<div class="grid create-layout"><div class="card"><h2>What will you share?</h2><p style="font-size:12px">Start with a topic your audience cares about.</p><form onsubmit="event.preventDefault();generateContent()"><div class="form-group"><label for="studio-agent">Expertise</label><select id="studio-agent">${db.agents.map((a,i)=>`<option value="${i}" ${i===dashAgent?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="form-group"><label for="studio-platform">Platform</label><select id="studio-platform"><option>LinkedIn</option><option>Instagram</option><option>X</option></select></div><div class="form-group"><label for="studio-topic">Topic or audience question</label><textarea class="field" id="studio-topic" rows="4" required placeholder="e.g. Building confidence as a new leader"></textarea></div><button class="primary" style="width:100%" id="generate-button">✧ Generate draft</button></form><p class="demo-note">Template-based demo generation</p></div><div class="card" id="draft-preview">${generated?draftPreview():`<div class="empty" style="padding-top:70px">${glyph(8)}<h2>Your next great idea starts here.</h2><p style="font-size:12px">Turn what you know into something<br>your audience can use.</p><span class="badge">Made for your voice</span></div>`}</div></div>${db.drafts.length?`<div class="section-title"><h2>Saved drafts</h2></div><div class="grid two">${db.drafts.map((d,i)=>`<button class="card" style="text-align:left" onclick="generated=db.drafts[${i}].text;render()"><span class="badge">${esc(d.platform)}</span><h3 style="margin-top:15px">${esc(d.topic)}</h3><small>Open draft →</small></button>`).join('')}</div>`:''}`}
let lastDraftMeta={};function generateContent(){let topic=$('#studio-topic').value.trim(),platform=$('#studio-platform').value,i=Number($('#studio-agent').value);if(!topic)return;lastDraftMeta={topic,platform};let q=db.qa.find(q=>q.agent===i);let idea=q?q.answer:'Start with a clear intention. Choose one small action you can put into practice today, ask for feedback, and build on what you learn.';generated=platform==='X'?`${topic}\n\nOne small step beats a perfect plan.\n\nChoose an action. Ask for feedback. Reflect. Repeat.\n\nWhat will you try today?`:`${topic}: small shifts, meaningful progress.\n\nThe best changes often start with a better question: what could I do differently today?\n\n${idea}\n\nTry this:\n→ Choose one situation to focus on.\n→ Put one principle into practice.\n→ Reflect on what changed, and share what you learned.\n\nWhat's one thing that has worked for you?\n\n#${db.agents[i].name.replace(/[^a-zA-Z]/g,'')} #ProfessionalGrowth`;$('#generate-button').disabled=true;$('#generate-button').innerHTML='Creating your draft <span class="thinking"><i></i><i></i><i></i></span>';setTimeout(()=>{$('#draft-preview').innerHTML=draftPreview();$('#generate-button').disabled=false;$('#generate-button').textContent='✧ Generate another draft'},1000)}
function draftPreview(){return `<div class="page-heading"><h2>Your draft</h2><span class="badge">Ready to make your own</span></div><textarea class="field generated" id="draft-text" rows="15" aria-label="Edit generated draft" oninput="generated=this.value">${esc(generated)}</textarea><div class="card-footer"><button class="outline" onclick="copyDraft()">Copy text</button><button class="primary" onclick="saveDraft()">Save draft</button></div><p class="demo-note">Review and personalize before sharing. This prototype does not publish posts.</p>`}
async function copyDraft(){try{await navigator.clipboard.writeText(generated);toast('Draft copied')}catch{downloadFile('xpertloop-draft.txt',generated);toast('Draft downloaded')}}function saveDraft(){db.drafts.unshift({text:generated,topic:lastDraftMeta.topic||'Untitled draft',platform:lastDraftMeta.platform||'LinkedIn'});save();toast('Draft saved');render()}
function profile(){modal('Your workspace',`<h2>${esc(db.profile.name)}</h2><p>${esc(db.profile.email)}</p><div style="display:grid;gap:8px">${[['profile','◎','Profile settings'],['account','⚙','Account settings'],['notifications','🔔','Notifications'],['billing','▱','Billing & plans'],['support','ⓘ','Help & support']].map(([r,i,t])=>`<button class="outline" style="text-align:left" onclick="closeModal();${r==='notifications'?'notificationsModal()':`go('${r}')`}">${i} &nbsp;${t} <span style="float:right">→</span></button>`).join('')}</div>`,`<button class="text-button red" onclick="signOut()">Sign out of demo →</button>`)}
function signOut(){modal('Sign out of demo',`<p>Your prototype data stays in this browser. Real authentication is not connected.</p>`,`<button class="outline" onclick="closeModal()">Stay here</button><button class="primary" onclick="closeModal();go('home');toast('Demo session restarted')">Restart demo session</button>`)}
function settings(r){if(r==='notifications')return heading('Notifications','Questions clients asked that your agents couldn’t answer.')+`<div class="card"><h2>Unanswered client questions</h2><p style="font-size:12px">Add your response to save it to the agent’s Q&A library and help it answer similar questions in future conversations.</p>${db.pending.map((q,i)=>`<div class="question-row"><div>${esc(q.question)}<small>${esc(db.agents[q.agent].name)} agent couldn’t answer this question</small></div><button class="secondary" onclick="answerQuestion(${i})">Add answer</button></div>`).join('')||'<p>You’re all caught up.</p>'}</div>`;if(r==='support')return heading('How can we help?','A little guidance for your Xpertloop workspace.')+`<div class="grid two">${[['How do I train my agent?','Open an agent and go to Content. Add resources under Files, or share specific answers under Q&A.'],['What happens to unanswered questions?','They appear in Analytics. Click Answer to add your perspective to the agent’s knowledge, then ask the same question in Chat.'],['Does this connect to an AI model?','This prototype uses local sample responses and your saved Q&A. It does not call an AI service.'],['Where is my data saved?','Changes are saved in this browser. Uploaded resources are metadata only. Billing and content generation use demo flows.']].map(([q,a])=>`<details class="card"><summary style="cursor:pointer;font-weight:550">${q}</summary><p style="font-size:12px;margin:15px 0 0">${a}</p></details>`).join('')}</div>`;if(r==='account')return heading('Account settings','Make this workspace work for you.')+`<div class="card" style="max-width:700px"><h2>Demo workspace</h2><p>This prototype saves your edits in your current browser.</p><h3 style="margin-top:30px">Export your workspace</h3><p style="font-size:12px">Download agents, Q&A, resource metadata, and drafts.</p><button class="outline" onclick="downloadFile('xpertloop-workspace.json',JSON.stringify(db,null,2),'application/json');toast('Workspace exported')">↓ Export demo data</button><h3 style="margin-top:35px">Reset demo data</h3><p style="font-size:12px">Restore the original sample workspace.</p><button class="outline red" onclick="resetModal()">Reset workspace</button></div>`;return heading('Profile settings','The person behind the expertise.')+`<form class="card" style="max-width:700px" onsubmit="event.preventDefault();db.profile.name=$('#profile-name').value;db.profile.email=$('#profile-email').value;save();toast('Profile saved')"><div class="avatar" style="width:65px;height:65px;font-size:18px;margin-bottom:28px">EJ</div><div class="form-group"><label for="profile-name">Full name</label><input required id="profile-name" value="${esc(db.profile.name)}"></div><div class="form-group"><label for="profile-email">Email address</label><input required type="email" id="profile-email" value="${esc(db.profile.email)}"></div><div class="form-group"><label for="profile-bio">Your expertise</label><textarea class="field" id="profile-bio" rows="4" placeholder="Tell clients about your approach…" oninput="db.profile.bio=this.value">${esc(db.profile.bio||'Executive coach helping leaders build confidence, clarity, and lasting impact.')}</textarea></div><button class="primary">Save changes</button></form>`}
function resetModal(){modal('Reset your workspace?',`<p>This removes your added agents, Q&A, drafts, and resource metadata from this browser and restores the original sample data.</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" onclick="db=structuredClone(initial);save();messages={};generated='';closeModal();go('home');toast('Sample workspace restored')">Reset demo data</button>`)}
function animateNumbers(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('[data-count]').forEach(el=>{let raw=el.dataset.count,n=Number(raw.replace(/[^0-9.]/g,'')),start=performance.now();function frame(now){let p=Math.min(1,(now-start)/750),value=Math.round(n*(1-Math.pow(1-p,3)));el.textContent=(raw.startsWith('$')?'$':'')+value.toLocaleString()+(raw.endsWith('%')?'%':'');if(p<1&&el.isConnected)requestAnimationFrame(frame)}requestAnimationFrame(frame)})}
render();

function notificationsModal(){
modal('Notifications',`<h3>Unanswered client questions</h3><p style="font-size:12px">Questions clients asked that your agents couldn’t answer. Add your response to save it to the agent’s Q&A library for future conversations.</p>${db.pending.map((q,i)=>`<div class="question-row"><div>${esc(q.question)}<small>${esc(db.agents[q.agent].name)} agent couldn’t answer this question</small></div><button class="secondary" style="flex-shrink:0" onclick="answerQuestion(${i})">Add answer</button></div>`).join('')||'<div class="empty"><h3>You’re all caught up</h3><p>Your agents have no unanswered client questions.</p></div>'}`,`<button class="outline" onclick="closeModal()">Close</button>`);
}
